import 'package:flutter/material.dart';
import '../../services/api_service.dart';
class SupervisorsScreen extends StatefulWidget{const SupervisorsScreen({super.key});@override State<SupervisorsScreen> createState()=>_SupervisorsScreenState();}
class _SupervisorsScreenState extends State<SupervisorsScreen>{List supervisors=[];bool loading=true;List<dynamic> list(dynamic x)=>x is List?List<dynamic>.from(x):(x is Map&&x['data'] is List?List<dynamic>.from(x['data']):[]);int id(dynamic x)=>int.tryParse('${x['id']}')??0;void msg(Object e)=>ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:Text(e.toString().replaceFirst('Exception: ',''))));@override void initState(){super.initState();load();}Future<void> load()async{try{final r=await ApiService.get('supervisors');if(mounted)setState((){supervisors=list(r);loading=false;});}catch(e){if(mounted){setState(()=>loading=false);msg(e);}}}
Future<void> form({dynamic item})async{final n=TextEditingController(text:'${item?['name']??''}'),p=TextEditingController(text:'${item?['phone']??''}'),e=TextEditingController(text:'${item?['email']??''}');final k=GlobalKey<FormState>();final ok=await showDialog<bool>(context:context,builder:(d)=>AlertDialog(title:Text(item==null?'إضافة مشرف':'تعديل المشرف'),content:Form(key:k,child:Column(mainAxisSize:MainAxisSize.min,children:[TextFormField(controller:n,decoration:const InputDecoration(labelText:'الاسم *'),validator:(v)=>v==null||v.trim().isEmpty?'مطلوب':null),TextFormField(controller:p,decoration:const InputDecoration(labelText:'الهاتف')),TextFormField(controller:e,decoration:const InputDecoration(labelText:'البريد'))])),actions:[TextButton(onPressed:()=>Navigator.pop(d,false),child:const Text('إلغاء')),FilledButton(onPressed:(){if(k.currentState!.validate())Navigator.pop(d,true);},child:const Text('حفظ'))]));if(ok==true){try{final b={'name':n.text.trim(),'phone':p.text.trim(),'email':e.text.trim()};if(item==null){b['status']='active';await ApiService.post('supervisors',b);}else{await ApiService.put('supervisors/${id(item)}',b);}await load();}catch(e){msg(e);}}for(final c in[n,p,e])c.dispose();}
Future<void> remove(dynamic s)async{final ok=await showDialog<bool>(context:context,builder:(d)=>AlertDialog(title:const Text('حذف المشرف'),content:Text('حذف ${s['name']??''}؟'),actions:[TextButton(onPressed:()=>Navigator.pop(d,false),child:const Text('إلغاء')),FilledButton(onPressed:()=>Navigator.pop(d,true),child:const Text('حذف'))]));if(ok==true){try{await ApiService.delete('supervisors/${id(s)}');await load();}catch(e){msg(e);}}}
Future<void> details(int sid)async{try{final r=await ApiService.get('supervisors/$sid');final d=Map<String,dynamic>.from(r is Map&&r['data'] is Map?r['data']:r);final pl=list(d['private_lessons']),gl=list(d['group_lessons']),h=list(d['lessons']);if(!mounted)return;await showDialog(context:context,builder:(x)=>AlertDialog(title:Text('${d['supervisor']?['name']??'المشرف'}'),content:SizedBox(width:500,child:SingleChildScrollView(child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text('خاصة: ${pl.length}'),Text('جروب: ${gl.length}'),Text('إجمالي: ${d['lessons_count']??0}'),Text('المستحق: ${d['due']??0}'),Text('المدفوع: ${d['paid']??0}'),Text('المتبقي: ${d['remaining']??0}'),Text('المكافآت: ${d['bonus_total']??0}'),const Divider(),Text('سجل الحصص: ${h.length}')]))),actions:[TextButton(onPressed:()=>Navigator.pop(x),child:const Text('إغلاق'))]));}catch(e){msg(e);}}
@override Widget build(BuildContext context)=>Scaffold(appBar:AppBar(title:const Text('المشرفون'),actions:[IconButton(onPressed:load,icon:const Icon(Icons.refresh))]),floatingActionButton:FloatingActionButton.extended(onPressed:()=>form(),icon:const Icon(Icons.person_add),label:const Text('إضافة مشرف')),body:loading?const Center(child:CircularProgressIndicator()):RefreshIndicator(onRefresh:load,child:ListView(padding:const EdgeInsets.fromLTRB(16,12,16,90),children:[if(supervisors.isEmpty)const Padding(padding:EdgeInsets.all(30),child:Center(child:Text('لا يوجد مشرفون.'))),...supervisors.map((s)=>Card(child:ListTile(onTap:()=>details(id(s)),leading:const CircleAvatar(child:Icon(Icons.supervisor_account)),title:Text('${s['name']??''}',style:const TextStyle(fontWeight:FontWeight.bold)),subtitle:Text('${s['lessons_count']??0} حصة'),trailing:Row(mainAxisSize:MainAxisSize.min,children:[IconButton(onPressed:()=>form(item:s),icon:const Icon(Icons.edit)),IconButton(onPressed:()=>remove(s),icon:const Icon(Icons.delete))]))))])));
}
